"""Record Nima's source-verified shared headwear binding without duplicate art."""
from pathlib import Path
from datetime import datetime,timezone
import hashlib,json
HERE=Path(__file__).resolve().parent;ROOT=HERE.parents[3];SOURCE=ROOT/'art/conversion/fit-human-female-wide-brimmed-hat/v1'
def ref(p):return dict(path=p.relative_to(ROOT).as_posix(),sha256=hashlib.sha256(p.read_bytes()).hexdigest())
def write(p,d):p.write_bytes((json.dumps(d,indent=2)+'\n').encode())
def refs(*ns):return [ref(HERE/n) for n in ns]
lp=ROOT/'evidence/conversion-ledger.json';ledger=json.loads(lp.read_text());entry=next(e for e in ledger['entries'] if e['id']=='FIT-NIMA-WIDE-BRIMMED-HAT-HEAD-0')
assert ledger['active_entry']==entry['id'] and not entry['generation_ready']
review='Checked Nima Ruda actual ordinary Head part 177, parent 176, manager null, laterality 0 and Wide-brimmed Hat instance 530. Item sprite and y/b palette match the current female canonical source; exact original unmutated female body, whole hat, band and zero skin-overlay registration are reused. Applicable SEN/mirrored-west, neutral/palette and intended-size inspection therefore covers identical art. Nima mutation/body assembly remains unfinished. No new ImageGen call, changed anatomy or native acceptance is claimed.'
write(HERE/'authoring-review.json',dict(status='GENERATION READY',workflow='regional-curved-v1',review=review,applicable_inspected_source_plates=[ref(SOURCE/n) for n in ['headwear-comparison.png','intact-garment-comparison.png','independent-palette-comparison.png','game-scale-review.png']],native_acceptance='Pending full-set generation gate'))
write(HERE/'artifact-manifest.json',dict(entry=entry['id'],files=[ref(p) for p in sorted(HERE.iterdir()) if p.is_file() and p.name!='artifact-manifest.json']))
def event(step,action,outs,source=[]):entry['process_log'].append(dict(timestamp=datetime.now(timezone.utc).isoformat(),step=step,action=action,inputs=refs('bind-shared-fit.py')+[ref(SOURCE/'model.json')]+source,outputs=outs,review=review,result='PASS',new_imagegen_call=False))
event('source_identity_description_slot_laterality','Bound actual Nima Ruda ordinary Head/0 and equipped hat to captured identity, sprite, description and palette. Retained independent mutation metadata.',refs('source-packet.json'))
event('select_correct_body_and_references','Selected exact shared unmutated female body and the hat original/CowboyHat reference packet; a named actor does not require a different race body.',refs('source-packet.json','registration-decisions.json'),[ref(SOURCE/'source-packet.json')])
event('construct_and_overlay_one_item','Reused the same whole-hat constructed crown, brim and lower-band region on the same original body/head. No refit or new geometry required.',refs('model.json'),[ref(SOURCE/'constructed-neutral-context.png'),ref(SOURCE/'pattern-south.svg'),ref(SOURCE/'pattern-east.svg'),ref(SOURCE/'pattern-north.svg')])
event('imagegen_refine_in_context_on_unchanged_body','Reused the actual canonical hat contextual refinement and exact prompt, without a redundant new call or generated body pixels.',[ref(SOURCE/'refined-red-context.png'),ref(SOURCE/'imagegen-prompt.txt'),ref(HERE/'source-packet.json')])
event('retrieve_isolated_item_and_masks','Reused exact continuous-hat/band assets, already completed from the same contextual source, and zero body-visibility masks. Kept a distinct named registration and actual binding.',refs('model.json','registration-decisions.json'),[ref(SOURCE/'registration-decisions.json'),ref(SOURCE/'intact-garment-comparison.png')])
event('recompose_check_cuffs_attachment_occlusion_all_views','Reused applicable reviewed composition for identical body/hat geometry in SEN/mirrored west; original skin stays behind the full hat.',[ref(SOURCE/'headwear-comparison.png'),ref(HERE/'authoring-review.json')])
event('review_game_scale_and_palette','Reused applicable intended-size and independent y-primary/b-band review. Body palette remains separately tintable.',[ref(SOURCE/'game-scale-review.png'),ref(SOURCE/'independent-palette-comparison.png'),ref(HERE/'authoring-review.json')])
event('reprocess_under_regional_curved_v1','Reconciled the actual individual binding to the current shared fit under the continuous-source/class-specific mask workflow. Body/NPC mutation entries remain pending.',refs('source-packet.json','registration-decisions.json','model.json','artifact-manifest.json'))
entry.update(status='UNFINISHED',generation_ready=True,current_step='native_equipment_state_review',current_registration=dict(model=ref(HERE/'model.json'),plate=ref(SOURCE/'headwear-comparison.png')),art_review=dict(status='PASS',reason=review),registration_summary='Exact current female hat art/body reused with actual Nima ordinary Head/0 binding; no new drawing or mutation assembly. Native pending.',native_acceptance='Pending final all-conversions gate');entry['apparel_workflow']['status']='GENERATION READY'
nxt=next(e for e in ledger['entries'] if e['id']=='ITEM-WIDE-BRIMMED-HAT');assert not nxt['generation_ready'] and nxt['status']=='UNFINISHED';nxt.update(status='IN PROGRESS',current_step='resolve_item_identity_description_palette');ledger['active_entry']=nxt['id'];ledger['updated_at']=datetime.now(timezone.utc).isoformat();write(lp,ledger)
print('Nima hat authoring recorded; hat item aggregate is the sole active entry.')
